const express=require('express');
const path=require('path');
const cookieParser=require('cookie-parser');
const helmet=require('helmet');
const rateLimit=require('express-rate-limit');
const bcrypt=require('bcryptjs');
const jwt=require('jsonwebtoken');
const multer=require('multer');
const QRCode=require('qrcode');
const {Pool}=require('pg');

const app=express();
const PORT=process.env.PORT||3000;
const JWT_SECRET=process.env.JWT_SECRET||'DEVELOPMENT_ONLY_CHANGE_ME';
const DATABASE_URL=process.env.DATABASE_URL;
if(!DATABASE_URL){console.error('DATABASE_URL tanımlı değil.');process.exit(1)}
const pool=new Pool({connectionString:DATABASE_URL,ssl:process.env.NODE_ENV==='production'?{rejectUnauthorized:false}:false});
const upload=multer({storage:multer.memoryStorage(),limits:{fileSize:5*1024*1024,files:1}});

app.set('trust proxy',1);
app.use(helmet({contentSecurityPolicy:false}));
app.use(express.json({limit:'700kb'}));
app.use(cookieParser());
app.use(express.static(path.join(__dirname,'public'),{maxAge:0,etag:true,setHeaders:res=>res.setHeader('Cache-Control','no-store, max-age=0')}));
app.use('/api/auth',rateLimit({windowMs:15*60*1000,max:60,standardHeaders:true,legacyHeaders:false}));

const clean=s=>String(s??'').trim();
const num=(v,d=0)=>Number.isFinite(Number(v))?Number(v):d;
const nil=v=>clean(v)||null;
const emailOk=s=>/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(s);
const companyRoles=['owner','manager','technician','operator','viewer'];
const roleLabel={owner:'Firma Sahibi',manager:'Yönetici',technician:'Teknisyen',operator:'Operatör',viewer:'Görüntüleyici'};
async function q(text,params=[]){return pool.query(text,params)}
function sign(u){return jwt.sign({id:u.id,email:u.email,name:u.name,role:u.role},JWT_SECRET,{expiresIn:'7d'})}
function setCookie(res,t){res.cookie('dm_token',t,{httpOnly:true,secure:process.env.NODE_ENV==='production',sameSite:'lax',maxAge:7*24*60*60*1000})}
function auth(req,res,next){const t=req.cookies.dm_token;if(!t)return res.status(401).json({error:'Giriş gerekli'});try{req.user=jwt.verify(t,JWT_SECRET);next()}catch{res.clearCookie('dm_token');res.status(401).json({error:'Oturum geçersiz'})}}
function siteAdmin(req,res,next){if(req.user?.role!=='admin')return res.status(403).json({error:'Site yöneticisi yetkisi gerekli'});next()}
function permit(...roles){return(req,res,next)=>{if(req.user?.role==='admin'||roles.includes(req.company?.role))return next();return res.status(403).json({error:`Bu işlem için yetkiniz yok (${roleLabel[req.company?.role]||'rol'})`})}}
function healthScore(m){let s=100;if(m.status==='Arızalı')s-=35;else if(m.status==='Bakımda')s-=15;else if(m.status==='Devre dışı')s-=25;if(m.criticality==='Kritik')s-=5;s-=Math.min(24,num(m.open_faults)*6);s-=Math.min(16,num(m.critical_faults)*8);s-=Math.min(21,num(m.overdue_maintenance)*7);s-=Math.min(9,num(m.due30)*3);if(num(m.faults90)>=3)s-=8;if(m.last_maintenance_date){const days=(Date.now()-new Date(m.last_maintenance_date).getTime())/86400000;if(days>180)s-=10}else if(num(m.hours)>250)s-=8;return Math.max(5,Math.min(100,Math.round(s)))}
function slug(s){return clean(s).toLocaleLowerCase('tr-TR').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/ı/g,'i').replace(/ğ/g,'g').replace(/ş/g,'s').replace(/ç/g,'c').replace(/ö/g,'o').replace(/ü/g,'u').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,40)||'firma'}
async function addCols(table,cols){for(const c of cols)await q(`ALTER TABLE ${table} ADD COLUMN IF NOT EXISTS ${c}`)}
async function uniqueCompanyCode(name){const base=slug(name);for(let i=0;i<20;i++){const code=(base+'-'+Math.random().toString(36).slice(2,7)).slice(0,60);if(!(await q('SELECT 1 FROM companies WHERE code=$1',[code])).rows.length)return code}return base+'-'+Date.now()}
async function createPersonalCompany(user){const name=`${user.name} Atölyesi`,code=await uniqueCompanyCode(name);const c=(await q('INSERT INTO companies(name,code,owner_user_id) VALUES($1,$2,$3) RETURNING *',[name,code,user.id])).rows[0];await q("INSERT INTO company_members(company_id,user_id,role) VALUES($1,$2,'owner') ON CONFLICT(company_id,user_id) DO UPDATE SET role='owner',is_active=true",[c.id,user.id]);await q('UPDATE users SET active_company_id=$1 WHERE id=$2',[c.id,user.id]);return c}
async function ensureCompanyForUser(userId){let u=(await q('SELECT id,name,active_company_id FROM users WHERE id=$1',[userId])).rows[0];if(!u)return null;let m=(await q(`SELECT c.id,c.name,c.code,cm.role FROM company_members cm JOIN companies c ON c.id=cm.company_id WHERE cm.user_id=$1 AND cm.is_active=true AND c.id=$2`,[userId,u.active_company_id||0])).rows[0];if(!m)m=(await q(`SELECT c.id,c.name,c.code,cm.role FROM company_members cm JOIN companies c ON c.id=cm.company_id WHERE cm.user_id=$1 AND cm.is_active=true ORDER BY cm.id LIMIT 1`,[userId])).rows[0];if(!m){const c=await createPersonalCompany(u);m={...c,role:'owner'}}if(Number(u.active_company_id)!==Number(m.id))await q('UPDATE users SET active_company_id=$1 WHERE id=$2',[m.id,userId]);return m}
async function companyCtx(req,res,next){try{const c=await ensureCompanyForUser(req.user.id);if(!c)return res.status(403).json({error:'Aktif firma bulunamadı'});req.company=c;next()}catch(e){next(e)}}
async function ownMachine(id,companyId){return (await q('SELECT id FROM machines WHERE id=$1 AND company_id=$2',[id,companyId])).rows[0]}
async function audit(req,action,entityType,entityId,details={}){try{await q('INSERT INTO audit_log(company_id,user_id,action,entity_type,entity_id,details) VALUES($1,$2,$3,$4,$5,$6::jsonb)',[req.company?.id||null,req.user?.id||null,action,entityType,entityId||null,JSON.stringify(details||{})])}catch(e){console.warn('audit:',e.message)}}
function validDateMonth(v){return /^\d{4}-\d{2}$/.test(String(v||''))?String(v):new Date().toISOString().slice(0,7)}

async function initDb(){
 await q(`CREATE TABLE IF NOT EXISTS users(id BIGSERIAL PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(200) UNIQUE NOT NULL,password_hash TEXT NOT NULL,role VARCHAR(20) NOT NULL DEFAULT 'user',is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
 await q(`CREATE TABLE IF NOT EXISTS companies(id BIGSERIAL PRIMARY KEY,name VARCHAR(180) NOT NULL,code VARCHAR(80) UNIQUE NOT NULL,owner_user_id BIGINT REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
 await q(`CREATE TABLE IF NOT EXISTS company_members(id BIGSERIAL PRIMARY KEY,company_id BIGINT NOT NULL REFERENCES companies(id) ON DELETE CASCADE,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,role VARCHAR(30) NOT NULL DEFAULT 'viewer',is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(company_id,user_id))`);
 await addCols('users',['active_company_id BIGINT']);
 await q(`CREATE TABLE IF NOT EXISTS machines(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,name VARCHAR(160) NOT NULL,model VARCHAR(160) DEFAULT '',hours NUMERIC(12,1) DEFAULT 0,criticality VARCHAR(30) DEFAULT 'Normal',serial_no VARCHAR(120) DEFAULT '',note TEXT DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
 await addCols('machines',["company_id BIGINT","manufacturer VARCHAR(160) DEFAULT ''","category VARCHAR(100) DEFAULT ''","location VARCHAR(180) DEFAULT ''","status VARCHAR(30) DEFAULT 'Çalışıyor'","power_kw NUMERIC(10,2) DEFAULT 0","year INTEGER","last_maintenance_date DATE","next_maintenance_date DATE","lubricant VARCHAR(180) DEFAULT ''","bearing_info TEXT DEFAULT ''","belt_info TEXT DEFAULT ''","motor_info TEXT DEFAULT ''"]);
 await q(`CREATE TABLE IF NOT EXISTS maintenance(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,machine_id BIGINT REFERENCES machines(id) ON DELETE CASCADE,task VARCHAR(220) NOT NULL,due_date DATE NOT NULL,priority VARCHAR(30) DEFAULT 'Normal',status VARCHAR(20) DEFAULT 'open',note TEXT DEFAULT '',completed_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
 await addCols('maintenance',["company_id BIGINT","maintenance_type VARCHAR(50) DEFAULT 'Periyodik'","frequency VARCHAR(80) DEFAULT ''","technician VARCHAR(160) DEFAULT ''","technician_user_id BIGINT","parts_used TEXT DEFAULT ''","cost NUMERIC(12,2) DEFAULT 0","duration_min INTEGER DEFAULT 0","meter_hours NUMERIC(12,1) DEFAULT 0"]);
 await q(`CREATE TABLE IF NOT EXISTS faults(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,machine_id BIGINT REFERENCES machines(id) ON DELETE SET NULL,system VARCHAR(40),symptom VARCHAR(180) NOT NULL,measurements JSONB DEFAULT '{}'::jsonb,note TEXT DEFAULT '',diagnosis TEXT DEFAULT '',status VARCHAR(20) DEFAULT 'open',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
 await addCols('faults',["company_id BIGINT","severity VARCHAR(30) DEFAULT 'Orta'","root_cause TEXT DEFAULT ''","action_taken TEXT DEFAULT ''","downtime_min INTEGER DEFAULT 0","closed_at TIMESTAMPTZ"]);
 await q(`CREATE TABLE IF NOT EXISTS parts(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,name VARCHAR(180) NOT NULL,part_code VARCHAR(120) DEFAULT '',category VARCHAR(80) DEFAULT '',quantity NUMERIC(12,2) DEFAULT 0,min_quantity NUMERIC(12,2) DEFAULT 0,unit VARCHAR(30) DEFAULT 'adet',location VARCHAR(140) DEFAULT '',supplier VARCHAR(180) DEFAULT '',unit_cost NUMERIC(12,2) DEFAULT 0,note TEXT DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
 await addCols('parts',['company_id BIGINT']);
 await q(`CREATE TABLE IF NOT EXISTS favorites(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,article_key VARCHAR(180) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(user_id,article_key))`);
 await q(`CREATE TABLE IF NOT EXISTS calc_history(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,tool VARCHAR(120) NOT NULL,input_data JSONB DEFAULT '{}'::jsonb,result TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
 await q(`CREATE TABLE IF NOT EXISTS work_orders(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,machine_id BIGINT REFERENCES machines(id) ON DELETE SET NULL,title VARCHAR(220) NOT NULL,description TEXT DEFAULT '',priority VARCHAR(30) DEFAULT 'Normal',status VARCHAR(30) DEFAULT 'open',assigned_to VARCHAR(160) DEFAULT '',due_date DATE,started_at TIMESTAMPTZ,completed_at TIMESTAMPTZ,parts_used TEXT DEFAULT '',cost NUMERIC(12,2) DEFAULT 0,downtime_min INTEGER DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
 await addCols('work_orders',['company_id BIGINT','assigned_user_id BIGINT']);
 await q(`CREATE TABLE IF NOT EXISTS machine_measurements(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,machine_id BIGINT NOT NULL REFERENCES machines(id) ON DELETE CASCADE,temperature NUMERIC(10,2),pressure NUMERIC(10,2),current_amp NUMERIC(10,2),voltage NUMERIC(10,2),vibration NUMERIC(10,3),rpm NUMERIC(12,1),note TEXT DEFAULT '',measured_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
 await addCols('machine_measurements',['company_id BIGINT']);
 await q(`CREATE TABLE IF NOT EXISTS attachments(id BIGSERIAL PRIMARY KEY,user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,machine_id BIGINT NOT NULL REFERENCES machines(id) ON DELETE CASCADE,file_name VARCHAR(240) NOT NULL,mime_type VARCHAR(120) NOT NULL,size_bytes INTEGER NOT NULL,file_data BYTEA NOT NULL,caption VARCHAR(240) DEFAULT '',created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);
 await addCols('attachments',['company_id BIGINT']);
 await q(`CREATE TABLE IF NOT EXISTS audit_log(id BIGSERIAL PRIMARY KEY,company_id BIGINT REFERENCES companies(id) ON DELETE CASCADE,user_id BIGINT REFERENCES users(id) ON DELETE SET NULL,action VARCHAR(80) NOT NULL,entity_type VARCHAR(80) NOT NULL,entity_id BIGINT,details JSONB DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW())`);

 const users=(await q('SELECT id,name,active_company_id FROM users ORDER BY id')).rows;
 for(const u of users)await ensureCompanyForUser(u.id);
 const shared=['machines','maintenance','faults','parts','work_orders','machine_measurements','attachments'];
 for(const t of shared)await q(`UPDATE ${t} x SET company_id=u.active_company_id FROM users u WHERE x.user_id=u.id AND x.company_id IS NULL`);
 await q('CREATE INDEX IF NOT EXISTS idx_machines_company ON machines(company_id)');
 await q('CREATE INDEX IF NOT EXISTS idx_maintenance_company_due ON maintenance(company_id,due_date)');
 await q('CREATE INDEX IF NOT EXISTS idx_faults_company_created ON faults(company_id,created_at)');
 await q('CREATE INDEX IF NOT EXISTS idx_work_company_due ON work_orders(company_id,due_date)');
 await q('CREATE INDEX IF NOT EXISTS idx_parts_company ON parts(company_id)');

 const ae=clean(process.env.ADMIN_EMAIL).toLowerCase(),ap=clean(process.env.ADMIN_PASSWORD);
 if(ae&&ap){const f=await q('SELECT id,name FROM users WHERE email=$1',[ae]);if(!f.rows.length){const h=await bcrypt.hash(ap,12);const u=(await q("INSERT INTO users(name,email,password_hash,role) VALUES($1,$2,$3,'admin') RETURNING id,name",[process.env.ADMIN_NAME||'Site Yöneticisi',ae,h])).rows[0];await createPersonalCompany(u)}else{await q("UPDATE users SET role='admin' WHERE email=$1",[ae]);await ensureCompanyForUser(f.rows[0].id)}}
}

// AUTH
app.post('/api/auth/register',async(req,res,next)=>{try{const name=clean(req.body.name),email=clean(req.body.email).toLowerCase(),password=String(req.body.password||'');if(name.length<2)return res.status(400).json({error:'Ad soyad gerekli'});if(!emailOk(email))return res.status(400).json({error:'Geçerli e-posta gir'});if(password.length<8)return res.status(400).json({error:'Şifre en az 8 karakter olmalı'});const h=await bcrypt.hash(password,12);const u=(await q('INSERT INTO users(name,email,password_hash) VALUES($1,$2,$3) RETURNING id,name,email,role,is_active,created_at',[name,email,h])).rows[0];await createPersonalCompany(u);setCookie(res,sign(u));res.json({user:u})}catch(e){if(e.code==='23505')return res.status(409).json({error:'Bu e-posta zaten kayıtlı'});next(e)}});
app.post('/api/auth/login',async(req,res,next)=>{try{const email=clean(req.body.email).toLowerCase(),password=String(req.body.password||'');const u=(await q('SELECT * FROM users WHERE email=$1',[email])).rows[0];if(!u||!(await bcrypt.compare(password,u.password_hash)))return res.status(401).json({error:'E-posta veya şifre hatalı'});if(!u.is_active)return res.status(403).json({error:'Hesabınız devre dışı'});await ensureCompanyForUser(u.id);setCookie(res,sign(u));res.json({user:{id:u.id,name:u.name,email:u.email,role:u.role,is_active:u.is_active}})}catch(e){next(e)}});
app.post('/api/auth/logout',(req,res)=>{res.clearCookie('dm_token');res.json({ok:true})});
app.get('/api/auth/me',auth,companyCtx,async(req,res)=>{const u=(await q('SELECT id,name,email,role,is_active,created_at,active_company_id FROM users WHERE id=$1',[req.user.id])).rows[0];if(!u?.is_active)return res.status(403).json({error:'Hesap devre dışı'});res.json({user:{...u,company:req.company,company_role:req.company.role}})});

// COMPANY / TEAM
app.get('/api/company',auth,companyCtx,async(req,res)=>{const companies=(await q(`SELECT c.id,c.name,c.code,cm.role,cm.is_active FROM company_members cm JOIN companies c ON c.id=cm.company_id WHERE cm.user_id=$1 AND cm.is_active=true ORDER BY c.name`,[req.user.id])).rows;const members=(await q(`SELECT u.id,u.name,u.email,cm.role,cm.is_active,cm.created_at FROM company_members cm JOIN users u ON u.id=cm.user_id WHERE cm.company_id=$1 ORDER BY CASE cm.role WHEN 'owner' THEN 0 WHEN 'manager' THEN 1 WHEN 'technician' THEN 2 WHEN 'operator' THEN 3 ELSE 4 END,u.name`,[req.company.id])).rows;res.json({active:req.company,companies,members,permissions:{canManageCompany:req.user.role==='admin'||['owner','manager'].includes(req.company.role),canManageRoles:req.user.role==='admin'||req.company.role==='owner',canEditAssets:req.user.role==='admin'||['owner','manager'].includes(req.company.role),canWork:req.user.role==='admin'||['owner','manager','technician'].includes(req.company.role),canOperate:req.user.role==='admin'||['owner','manager','technician','operator'].includes(req.company.role)}})});
app.post('/api/company',auth,async(req,res,next)=>{try{const name=clean(req.body.name);if(name.length<2)return res.status(400).json({error:'Firma adı gerekli'});const code=await uniqueCompanyCode(name);const c=(await q('INSERT INTO companies(name,code,owner_user_id) VALUES($1,$2,$3) RETURNING *',[name,code,req.user.id])).rows[0];await q("INSERT INTO company_members(company_id,user_id,role) VALUES($1,$2,'owner')",[c.id,req.user.id]);await q('UPDATE users SET active_company_id=$1 WHERE id=$2',[c.id,req.user.id]);res.json(c)}catch(e){next(e)}});
app.post('/api/company/switch/:id',auth,async(req,res)=>{const m=(await q(`SELECT c.id,c.name,c.code,cm.role FROM company_members cm JOIN companies c ON c.id=cm.company_id WHERE cm.user_id=$1 AND cm.company_id=$2 AND cm.is_active=true`,[req.user.id,req.params.id])).rows[0];if(!m)return res.status(403).json({error:'Bu firmaya erişiminiz yok'});await q('UPDATE users SET active_company_id=$1 WHERE id=$2',[m.id,req.user.id]);res.json(m)});
app.patch('/api/company',auth,companyCtx,permit('owner','manager'),async(req,res)=>{const name=clean(req.body.name);if(name.length<2)return res.status(400).json({error:'Firma adı gerekli'});const c=(await q('UPDATE companies SET name=$1 WHERE id=$2 RETURNING id,name,code',[name,req.company.id])).rows[0];await audit(req,'update','company',req.company.id,{name});res.json(c)});
app.post('/api/company/members',auth,companyCtx,permit('owner','manager'),async(req,res)=>{const email=clean(req.body.email).toLowerCase(),role=companyRoles.includes(req.body.role)?req.body.role:'viewer';if(role==='owner'&&req.company.role!=='owner'&&req.user.role!=='admin')return res.status(403).json({error:'Sadece firma sahibi yeni sahip atayabilir'});const u=(await q('SELECT id,name,email,is_active FROM users WHERE email=$1',[email])).rows[0];if(!u)return res.status(404).json({error:'Bu e-posta ile kayıtlı kullanıcı yok. Önce siteye kayıt olması gerekir.'});if(!u.is_active)return res.status(400).json({error:'Bu kullanıcı pasif'});await q(`INSERT INTO company_members(company_id,user_id,role,is_active) VALUES($1,$2,$3,true) ON CONFLICT(company_id,user_id) DO UPDATE SET role=EXCLUDED.role,is_active=true`,[req.company.id,u.id,role]);await audit(req,'member_add','company_member',u.id,{email,role});res.json({ok:true,user:u,role})});
app.patch('/api/company/members/:userId',auth,companyCtx,permit('owner'),async(req,res)=>{if(Number(req.params.userId)===Number(req.user.id)&&req.body.role!=='owner')return res.status(400).json({error:'Kendi firma sahibi rolünüzü kaldıramazsınız'});const role=companyRoles.includes(req.body.role)?req.body.role:'viewer';await q('UPDATE company_members SET role=$1,is_active=true WHERE company_id=$2 AND user_id=$3',[role,req.company.id,req.params.userId]);await audit(req,'member_role','company_member',req.params.userId,{role});res.json({ok:true})});
app.delete('/api/company/members/:userId',auth,companyCtx,permit('owner','manager'),async(req,res)=>{if(Number(req.params.userId)===Number(req.user.id))return res.status(400).json({error:'Kendinizi aktif firmadan çıkaramazsınız'});const target=(await q('SELECT role FROM company_members WHERE company_id=$1 AND user_id=$2',[req.company.id,req.params.userId])).rows[0];if(target?.role==='owner'&&req.company.role!=='owner'&&req.user.role!=='admin')return res.status(403).json({error:'Firma sahibi kaldırılamaz'});await q('UPDATE company_members SET is_active=false WHERE company_id=$1 AND user_id=$2',[req.company.id,req.params.userId]);await audit(req,'member_remove','company_member',req.params.userId,{});res.json({ok:true})});
app.get('/api/audit',auth,companyCtx,async(req,res)=>{const limit=Math.min(200,Math.max(10,num(req.query.limit,60)));res.json((await q(`SELECT a.*,u.name user_name FROM audit_log a LEFT JOIN users u ON u.id=a.user_id WHERE a.company_id=$1 ORDER BY a.id DESC LIMIT $2`,[req.company.id,limit])).rows)});

// MACHINES
const machineStats=`(SELECT COUNT(*) FROM faults f WHERE f.machine_id=m.id AND f.company_id=m.company_id AND f.status='open')::int open_faults,(SELECT COUNT(*) FROM faults f WHERE f.machine_id=m.id AND f.company_id=m.company_id AND f.status='open' AND f.severity='Kritik')::int critical_faults,(SELECT COUNT(*) FROM faults f WHERE f.machine_id=m.id AND f.company_id=m.company_id AND f.created_at>=NOW()-INTERVAL '90 days')::int faults90,(SELECT COUNT(*) FROM maintenance x WHERE x.machine_id=m.id AND x.company_id=m.company_id AND x.status='open' AND x.due_date<CURRENT_DATE)::int overdue_maintenance,(SELECT COUNT(*) FROM maintenance x WHERE x.machine_id=m.id AND x.company_id=m.company_id AND x.status='open' AND x.due_date BETWEEN CURRENT_DATE AND CURRENT_DATE+30)::int due30`;
app.get('/api/machines',auth,companyCtx,async(req,res)=>{const r=await q(`SELECT m.*,${machineStats} FROM machines m WHERE m.company_id=$1 ORDER BY m.id DESC`,[req.company.id]);res.json(r.rows.map(x=>({...x,health_score:healthScore(x)})))});
app.get('/api/machines/:id/detail',auth,companyCtx,async(req,res)=>{const m=(await q(`SELECT m.*,${machineStats} FROM machines m WHERE m.id=$1 AND m.company_id=$2`,[req.params.id,req.company.id])).rows[0];if(!m)return res.status(404).json({error:'Makine bulunamadı'});const [ma,f,w,ms,a]=await Promise.all([q('SELECT * FROM maintenance WHERE machine_id=$1 AND company_id=$2 ORDER BY due_date DESC,id DESC LIMIT 80',[m.id,req.company.id]),q('SELECT * FROM faults WHERE machine_id=$1 AND company_id=$2 ORDER BY id DESC LIMIT 80',[m.id,req.company.id]),q('SELECT * FROM work_orders WHERE machine_id=$1 AND company_id=$2 ORDER BY id DESC LIMIT 80',[m.id,req.company.id]),q('SELECT * FROM machine_measurements WHERE machine_id=$1 AND company_id=$2 ORDER BY measured_at DESC LIMIT 120',[m.id,req.company.id]),q('SELECT id,file_name,mime_type,size_bytes,caption,created_at FROM attachments WHERE machine_id=$1 AND company_id=$2 ORDER BY id DESC LIMIT 80',[m.id,req.company.id])]);m.health_score=healthScore(m);res.json({machine:m,maintenance:ma.rows,faults:f.rows,workOrders:w.rows,measurements:ms.rows.reverse(),attachments:a.rows})});
