app.post('/api/work-orders',auth,companyCtx,permit('owner','manager','technician'),async(req,res)=>{const b=req.body;if(!clean(b.title))return res.status(400).json({error:'İş emri başlığı gerekli'});if(b.machine_id&&!(await ownMachine(b.machine_id,req.company.id)))return res.status(403).json({error:'Makine aktif firmaya ait değil'});const r=await q(`INSERT INTO work_orders(user_id,company_id,machine_id,title,description,priority,status,assigned_to,assigned_user_id,due_date,parts_used,cost,downtime_min) VALUES($1,$2,$3,$4,$5,$6,'open',$7,$8,$9,$10,$11,$12) RETURNING *`,[req.user.id,req.company.id,b.machine_id||null,clean(b.title),clean(b.description),clean(b.priority)||'Normal',clean(b.assigned_to),b.assigned_user_id||null,nil(b.due_date),clean(b.parts_used),num(b.cost),Math.round(num(b.downtime_min))]);await audit(req,'create','work_order',r.rows[0].id,{title:r.rows[0].title});res.json(r.rows[0])});
app.patch('/api/work-orders/:id',auth,companyCtx,permit('owner','manager','technician'),async(req,res)=>{const allowed=['open','in_progress','waiting','done'],st=allowed.includes(req.body.status)?req.body.status:'open';const r=await q(`UPDATE work_orders SET status=$1,assigned_to=COALESCE($2,assigned_to),assigned_user_id=COALESCE($3,assigned_user_id),parts_used=COALESCE($4,parts_used),cost=COALESCE($5,cost),downtime_min=COALESCE($6,downtime_min),started_at=CASE WHEN $1='in_progress' AND started_at IS NULL THEN NOW() ELSE started_at END,completed_at=CASE WHEN $1='done' THEN NOW() WHEN $1<>'done' THEN NULL ELSE completed_at END WHERE id=$7 AND company_id=$8 RETURNING *`,[st,req.body.assigned_to??null,req.body.assigned_user_id??null,req.body.parts_used??null,req.body.cost===undefined?null:num(req.body.cost),req.body.downtime_min===undefined?null:Math.round(num(req.body.downtime_min)),req.params.id,req.company.id]);if(!r.rows[0])return res.status(404).json({error:'İş emri bulunamadı'});await audit(req,st==='done'?'complete':'update','work_order',req.params.id,{status:st,title:r.rows[0].title});res.json(r.rows[0])});
