const allowedMime=new Set(['image/jpeg','image/png','image/webp','application/pdf','text/plain','application/msword','application/vnd.openxmlformats-officedocument.wordprocessingml.document']);
app.post('/api/machines/:id/attachments',auth,companyCtx,permit('owner','manager','technician','operator'),upload.single('file'),async(req,res)=>{if(!(await ownMachine(req.params.id,req.company.id)))return res.status(404).json({error:'Makine bulunamadı'});if(!req.file)return res.status(400).json({error:'Dosya seçilmedi'});if(!allowedMime.has(req.file.mimetype))return res.status(415).json({error:'Desteklenmeyen dosya türü'});const r=await q(`INSERT INTO attachments(user_id,company_id,machine_id,file_name,mime_type,size_bytes,file_data,caption) VALUES($1,$2,$3,$4,$5,$6,$7,$8) RETURNING id,file_name,mime_type,size_bytes,caption,created_at`,[req.user.id,req.company.id,req.params.id,clean(req.file.originalname).slice(0,240),req.file.mimetype,req.file.size,req.file.buffer,clean(req.body.caption).slice(0,240)]);await audit(req,'create','attachment',r.rows[0].id,{file_name:r.rows[0].file_name});res.json(r.rows[0])});
app.get('/api/attachments/:id',auth,companyCtx,async(req,res)=>{const a=(await q('SELECT file_name,mime_type,file_data FROM attachments WHERE id=$1 AND company_id=$2',[req.params.id,req.company.id])).rows[0];if(!a)return res.status(404).end();res.setHeader('Content-Type',a.mime_type);res.setHeader('Content-Disposition',`inline; filename*=UTF-8''${encodeURIComponent(a.file_name)}`);res.send(a.file_data)});
app.delete('/api/attachments/:id',auth,companyCtx,permit('owner','manager','technician'),async(req,res)=>{await q('DELETE FROM attachments WHERE id=$1 AND company_id=$2',[req.params.id,req.company.id]);res.json({ok:true})});
app.get('/api/machines/:id/qr',auth,companyCtx,async(req,res)=>{const m=(await q('SELECT id,name FROM machines WHERE id=$1 AND company_id=$2',[req.params.id,req.company.id])).rows[0];if(!m)return res.status(404).json({error:'Makine bulunamadı'});const base=`${req.protocol}://${req.get('host')}`,url=`${base}/?machine=${m.id}`;const svg=await QRCode.toString(url,{type:'svg',margin:1,width:360,errorCorrectionLevel:'M'});res.type('image/svg+xml').send(svg)});

