app.get('/api/calendar',auth,companyCtx,async(req,res)=>{const month=validDateMonth(req.query.month);const [y,m]=month.split('-').map(Number),start=`${month}-01`,next=m===12?`${y+1}-01-01`:`${y}-${String(m+1).padStart(2,'0')}-01`;const [ma,wo]=await Promise.all([q(`SELECT ma.id,ma.task title,ma.due_date date,ma.status,ma.priority,ma.maintenance_type type,x.name machine_name,'maintenance' kind FROM maintenance ma LEFT JOIN machines x ON x.id=ma.machine_id WHERE ma.company_id=$1 AND ma.due_date >= $2::date AND ma.due_date < $3::date ORDER BY ma.due_date`,[req.company.id,start,next]),q(`SELECT w.id,w.title,w.due_date date,w.status,w.priority,'İş Emri' type,m.name machine_name,'work' kind FROM work_orders w LEFT JOIN machines m ON m.id=w.machine_id WHERE w.company_id=$1 AND w.due_date >= $2::date AND w.due_date < $3::date ORDER BY w.due_date`,[req.company.id,start,next])]);res.json({month,events:[...ma.rows,...wo.rows].sort((a,b)=>String(a.date).localeCompare(String(b.date)))})});

// ADVANCED FAULT ANALYTICS
app.get('/api/analytics/faults',auth,companyCtx,async(req,res)=>{const days=Math.min(730,Math.max(7,Math.round(num(req.query.days,90))));const params=[req.company.id,days];const [sum,systems,severity,recurrent,machinesR,roots,trend]=await Promise.all([
 q(`SELECT COUNT(*)::int total,COUNT(*) FILTER(WHERE status='open')::int open,COUNT(*) FILTER(WHERE status='closed')::int closed,COALESCE(SUM(downtime_min),0)::int downtime_min,COALESCE(ROUND(AVG(downtime_min) FILTER(WHERE status='closed')),0)::int avg_downtime_min,COALESCE(ROUND(AVG(EXTRACT(EPOCH FROM(closed_at-created_at))/60) FILTER(WHERE closed_at IS NOT NULL)),0)::int mttr_min FROM faults WHERE company_id=$1 AND created_at>=NOW()-make_interval(days=>$2::int)`,params),
 q(`SELECT COALESCE(NULLIF(system,''),'Diğer') label,COUNT(*)::int value FROM faults WHERE company_id=$1 AND created_at>=NOW()-make_interval(days=>$2::int) GROUP BY 1 ORDER BY value DESC LIMIT 12`,params),
 q(`SELECT COALESCE(NULLIF(severity,''),'Orta') label,COUNT(*)::int value FROM faults WHERE company_id=$1 AND created_at>=NOW()-make_interval(days=>$2::int) GROUP BY 1 ORDER BY value DESC`,params),
 q(`SELECT symptom label,COUNT(*)::int value,COALESCE(SUM(downtime_min),0)::int downtime_min FROM faults WHERE company_id=$1 AND created_at>=NOW()-make_interval(days=>$2::int) GROUP BY symptom HAVING COUNT(*)>1 ORDER BY value DESC,downtime_min DESC LIMIT 10`,params),
 q(`SELECT COALESCE(m.name,'Makine seçilmedi') label,COUNT(*)::int value,COALESCE(SUM(f.downtime_min),0)::int downtime_min FROM faults f LEFT JOIN machines m ON m.id=f.machine_id WHERE f.company_id=$1 AND f.created_at>=NOW()-make_interval(days=>$2::int) GROUP BY m.name ORDER BY value DESC,downtime_min DESC LIMIT 10`,params),
 q(`SELECT root_cause label,COUNT(*)::int value FROM faults WHERE company_id=$1 AND created_at>=NOW()-make_interval(days=>$2::int) AND NULLIF(TRIM(root_cause),'') IS NOT NULL GROUP BY root_cause ORDER BY value DESC LIMIT 10`,params),
 q(`SELECT to_char(date_trunc('month',created_at),'YYYY-MM') month,COUNT(*)::int value,COALESCE(SUM(downtime_min),0)::int downtime_min FROM faults WHERE company_id=$1 AND created_at>=NOW()-make_interval(days=>$2::int) GROUP BY 1 ORDER BY 1`,params)
]);res.json({days,summary:sum.rows[0],systems:systems.rows,severity:severity.rows,recurrent:recurrent.rows,machines:machinesR.rows,rootCauses:roots.rows,trend:trend.rows})});

// SERVICE REPORT DATA — frontend turns this into print/PDF view
app.get('/api/reports/maintenance/:id',auth,companyCtx,async(req,res)=>{const r=(await q(`SELECT ma.*,m.name machine_name,m.manufacturer,m.model,m.serial_no,m.location,c.name company_name,u.name created_by_name FROM maintenance ma LEFT JOIN machines m ON m.id=ma.machine_id LEFT JOIN companies c ON c.id=ma.company_id LEFT JOIN users u ON u.id=ma.user_id WHERE ma.id=$1 AND ma.company_id=$2`,[req.params.id,req.company.id])).rows[0];if(!r)return res.status(404).json({error:'Bakım kaydı bulunamadı'});res.json({type:'maintenance',report_no:`SRV-B-${String(r.id).padStart(6,'0')}`,record:r,generated_at:new Date().toISOString(),generated_by:req.user.name})});
app.get('/api/reports/work-order/:id',auth,companyCtx,async(req,res)=>{const r=(await q(`SELECT w.*,m.name machine_name,m.manufacturer,m.model,m.serial_no,m.location,c.name company_name,u.name created_by_name FROM work_orders w LEFT JOIN machines m ON m.id=w.machine_id LEFT JOIN companies c ON c.id=w.company_id LEFT JOIN users u ON u.id=w.user_id WHERE w.id=$1 AND w.company_id=$2`,[req.params.id,req.company.id])).rows[0];if(!r)return res.status(404).json({error:'İş emri bulunamadı'});res.json({type:'work_order',report_no:`SRV-I-${String(r.id).padStart(6,'0')}`,record:r,generated_at:new Date().toISOString(),generated_by:req.user.name})});

// NOTIFICATIONS / DASHBOARD
app.get('/api/notifications',auth,companyCtx,async(req,res)=>{const c=req.company.id;const [ma,f,p,w]=await Promise.all([q(`SELECT ma.id,ma.task title,ma.due_date,x.name machine_name FROM maintenance ma LEFT JOIN machines x ON x.id=ma.machine_id WHERE ma.company_id=$1 AND ma.status='open' AND ma.due_date<=CURRENT_DATE+7 ORDER BY ma.due_date LIMIT 20`,[c]),q(`SELECT f.id,f.symptom title,f.severity,x.name machine_name,f.created_at FROM faults f LEFT JOIN machines x ON x.id=f.machine_id WHERE f.company_id=$1 AND f.status='open' AND f.severity IN ('Yüksek','Kritik') ORDER BY f.id DESC LIMIT 20`,[c]),q(`SELECT id,name title,quantity,min_quantity,unit FROM parts WHERE company_id=$1 AND quantity<=min_quantity ORDER BY quantity-min_quantity LIMIT 20`,[c]),q(`SELECT w.id,w.title,w.due_date,w.priority,m.name machine_name FROM work_orders w LEFT JOIN machines m ON m.id=w.machine_id WHERE w.company_id=$1 AND w.status<>'done' AND (w.due_date IS NULL OR w.due_date<=CURRENT_DATE+7) ORDER BY w.due_date NULLS LAST LIMIT 20`,[c])]);const n=[];ma.rows.forEach(x=>n.push({type:'maintenance',level:new Date(x.due_date)<new Date(new Date().toDateString())?'critical':'warning',title:x.title,detail:`${x.machine_name||'Makine'} • ${x.due_date}`,target:'maintenance'}));f.rows.forEach(x=>n.push({type:'fault',level:x.severity==='Kritik'?'critical':'warning',title:x.title,detail:`${x.machine_name||'Makine'} • ${x.severity}`,target:'diagnosis'}));p.rows.forEach(x=>n.push({type:'stock',level:'warning',title:`Düşük stok: ${x.title}`,detail:`${x.quantity} ${x.unit} / min ${x.min_quantity}`,target:'parts'}));w.rows.forEach(x=>n.push({type:'work',level:x.priority==='Kritik'?'critical':'info',title:x.title,detail:`${x.machine_name||'Makine'}${x.due_date?' • '+x.due_date:''}`,target:'workorders'}));res.json(n.slice(0,50))});
app.get('/api/dashboard',auth,companyCtx,async(req,res)=>{const c=req.company.id;const [m,ma,f,od,d30,done,crit,low,cost,rm,rf,wo]=await Promise.all([q('SELECT COUNT(*)::int c FROM machines WHERE company_id=$1',[c]),q("SELECT COUNT(*)::int c FROM maintenance WHERE company_id=$1 AND status='open'",[c]),q("SELECT COUNT(*)::int c FROM faults WHERE company_id=$1 AND status='open'",[c]),q("SELECT COUNT(*)::int c FROM maintenance WHERE company_id=$1 AND status='open' AND due_date<CURRENT_DATE",[c]),q("SELECT COUNT(*)::int c FROM maintenance WHERE company_id=$1 AND status='open' AND due_date BETWEEN CURRENT_DATE AND CURRENT_DATE+30",[c]),q("SELECT COUNT(*)::int c FROM maintenance WHERE company_id=$1 AND status='done' AND completed_at>=date_trunc('month',NOW())",[c]),q("SELECT COUNT(*)::int c FROM machines WHERE company_id=$1 AND (criticality='Kritik' OR status IN ('Arızalı','Bakımda'))",[c]),q('SELECT COUNT(*)::int c FROM parts WHERE company_id=$1 AND quantity<=min_quantity',[c]),q("SELECT COALESCE(SUM(cost),0)::numeric t FROM maintenance WHERE company_id=$1 AND completed_at>=date_trunc('month',NOW())",[c]),q(`SELECT ma.id,ma.task,ma.due_date,ma.status,ma.priority,x.name machine_name FROM maintenance ma LEFT JOIN machines x ON x.id=ma.machine_id WHERE ma.company_id=$1 ORDER BY ma.created_at DESC LIMIT 6`,[c]),q(`SELECT f.id,f.symptom,f.status,f.severity,f.created_at,x.name machine_name FROM faults f LEFT JOIN machines x ON x.id=f.machine_id WHERE f.company_id=$1 ORDER BY f.created_at DESC LIMIT 6`,[c]),q("SELECT COUNT(*)::int c FROM work_orders WHERE company_id=$1 AND status<>'done'",[c])]);const ms=await q(`SELECT m.*,${machineStats} FROM machines m WHERE m.company_id=$1`,[c]);const scores=ms.rows.map(healthScore),avgHealth=scores.length?Math.round(scores.reduce((a,b)=>a+b,0)/scores.length):0;res.json({machines:m.rows[0].c,maintenance:ma.rows[0].c,faults:f.rows[0].c,overdue:od.rows[0].c,due30:d30.rows[0].c,doneMonth:done.rows[0].c,critical:crit.rows[0].c,lowStock:low.rows[0].c,costMonth:Number(cost.rows[0].t||0),openWorkOrders:wo.rows[0].c,avgHealth,recentMaintenance:rm.rows,recentFaults:rf.rows,company:req.company})});

// SITE ADMIN
app.get('/api/admin/summary',auth,siteAdmin,async(req,res)=>{const r=await q(`SELECT (SELECT COUNT(*) FROM users)::int users,(SELECT COUNT(*) FROM users WHERE is_active)::int active_users,(SELECT COUNT(*) FROM users WHERE NOT is_active)::int inactive_users,(SELECT COUNT(*) FROM companies)::int companies,(SELECT COUNT(*) FROM machines)::int machines,(SELECT COUNT(*) FROM maintenance)::int maintenance,(SELECT COUNT(*) FROM faults)::int faults,(SELECT COUNT(*) FROM parts)::int parts,(SELECT COUNT(*) FROM work_orders)::int work_orders,(SELECT COUNT(*) FROM attachments)::int attachments`);res.json(r.rows[0])});
app.get('/api/admin/users',auth,siteAdmin,async(req,res)=>{const term=`%${clean(req.query.search)}%`;const r=await q(`SELECT u.id,u.name,u.email,u.role,u.is_active,u.created_at,(SELECT COUNT(*) FROM company_members cm WHERE cm.user_id=u.id AND cm.is_active)::int companies,(SELECT COUNT(*) FROM machines m WHERE m.user_id=u.id)::int machines,(SELECT COUNT(*) FROM maintenance ma WHERE ma.user_id=u.id)::int maintenance,(SELECT COUNT(*) FROM faults f WHERE f.user_id=u.id)::int faults,(SELECT COUNT(*) FROM parts p WHERE p.user_id=u.id)::int parts FROM users u WHERE ($1='%%' OR u.name ILIKE $1 OR u.email ILIKE $1) ORDER BY u.id DESC LIMIT 500`,[term]);res.json(r.rows)});
app.get('/api/admin/users/:id',auth,siteAdmin,async(req,res)=>{const u=(await q('SELECT id,name,email,role,is_active,created_at FROM users WHERE id=$1',[req.params.id])).rows[0];if(!u)return res.status(404).json({error:'Kullanıcı bulunamadı'});const [m,ma,f,p,cs]=await Promise.all([q('SELECT * FROM machines WHERE user_id=$1 ORDER BY id DESC LIMIT 50',[u.id]),q('SELECT ma.*,x.name machine_name FROM maintenance ma LEFT JOIN machines x ON x.id=ma.machine_id WHERE ma.user_id=$1 ORDER BY ma.id DESC LIMIT 50',[u.id]),q('SELECT f.*,x.name machine_name FROM faults f LEFT JOIN machines x ON x.id=f.machine_id WHERE f.user_id=$1 ORDER BY f.id DESC LIMIT 50',[u.id]),q('SELECT * FROM parts WHERE user_id=$1 ORDER BY name LIMIT 50',[u.id]),q(`SELECT c.id,c.name,cm.role FROM company_members cm JOIN companies c ON c.id=cm.company_id WHERE cm.user_id=$1 AND cm.is_active`,[u.id])]);res.json({user:u,machines:m.rows,maintenance:ma.rows,faults:f.rows,parts:p.rows,companies:cs.rows})});
app.patch('/api/admin/users/:id/active',auth,siteAdmin,async(req,res)=>{if(Number(req.params.id)===Number(req.user.id))return res.status(400).json({error:'Kendi admin hesabınızı devre dışı bırakamazsınız'});const r=await q('UPDATE users SET is_active=$1 WHERE id=$2 RETURNING id,name,email,role,is_active',[!!req.body.is_active,req.params.id]);res.json(r.rows[0]||{})});
app.patch('/api/admin/users/:id/role',auth,siteAdmin,async(req,res)=>{if(Number(req.params.id)===Number(req.user.id)&&req.body.role!=='admin')return res.status(400).json({error:'Kendi admin rolünüzü kaldıramazsınız'});const role=req.body.role==='admin'?'admin':'user';const r=await q('UPDATE users SET role=$1 WHERE id=$2 RETURNING id,name,email,role,is_active',[role,req.params.id]);res.json(r.rows[0]||{})});
app.delete('/api/admin/users/:id',auth,siteAdmin,async(req,res)=>{if(Number(req.params.id)===Number(req.user.id))return res.status(400).json({error:'Kendi admin hesabınızı silemezsiniz'});await q('DELETE FROM users WHERE id=$1',[req.params.id]);res.json({ok:true})});

